"""
Purpose: the orderable or purchasable test as a laboratory or vendor offers it (Labcorp 001453 'Hemoglobin (Hb) A1c',
Quest 496, Jinfiniti Intracellular NAD test, TruAge report). Panels are LabTests of kind PANEL that INCLUDE other
LabTests (absorbs pinned PanelDefinition; composition changes are episodes). What it measures (MEASURES_METRIC) and
how (PERFORMED_WITH_VERSION) change over time and are therefore episodes; price and offers are D6.
Identity rule: (issuer, issuer's test code) via the kernel Identifier (scheme LAB_TEST_CODE, requested); else
(issuer, verbatim test name). uid token: `lab-test`.
Questions: CQ-DX-01, Q-D4-01, Q-D4-03, Q-D4-04, Q-D4-12, Q-D4-13, Q-D4-18, Q-D4-19, Q-D4-23, Q-D4-24, Q-D4-25.
"""
type LabTest implements Entity & Subjectable
  @node(labels: ["LabTest", "Entity"])
  @query(aggregate: false)
  @mutation(operations: []) {
  id: ID!
  uid: String!
  name: String
  privacyClass: PrivacyClass
  lastWriterRunId: String
  createdAt: DateTime
  updatedAt: DateTime
  testKind: LabTestKind!
  orderChannel: OrderChannel
  collectionModes: [CollectionMode!]
  "Specimen requirements as written (tube, volume, container)."
  specimenText: String
  "Patient preparation, stability and rejection criteria as written (Q-D4-19)."
  preAnalyticalText: String
  notReported: [MeasurementField!]
  """class: asserted; cardinality: one_or_more (episode: labs remap result codes to LOINC); questions: CQ-DX-01, Q-D4-01, Q-D4-03, Q-D4-17, Q-D4-25."""
  metrics: [Metric!]!
    @relationship(type: "MEASURES_METRIC", direction: OUT, properties: "AssertedEdgeProperties", nestedOperations: [CONNECT], aggregate: false)
    @filterable(byValue: true, byAggregate: false)
  """class: asserted; cardinality: many (episode: a method or instrument change closes one and opens the next; several open when regional labs differ); questions: CQ-DX-01, CQ-DX-03, Q-D4-01, Q-D4-02, Q-D4-11, Q-D4-23."""
  assayVersions: [AssayVersion!]!
    @relationship(type: "PERFORMED_WITH_VERSION", direction: OUT, properties: "AssertedEdgeProperties", nestedOperations: [CONNECT], aggregate: false)
    @filterable(byValue: true, byAggregate: false)
  """class: asserted; cardinality: many (episode: a report's algorithm implementation changes); questions: CQ-DX-02, CQ-DX-04, Q-D4-04, Q-D4-06, Q-D4-20, Q-D4-23."""
  algorithmVersions: [AlgorithmVersion!]!
    @relationship(type: "PERFORMED_WITH_VERSION", direction: OUT, properties: "AssertedEdgeProperties", nestedOperations: [CONNECT], aggregate: false)
    @filterable(byValue: true, byAggregate: false)
  """class: asserted; cardinality: many (PANEL only; episode = panel composition version); questions: Q-D4-03, Q-D4-25."""
  components: [LabTest!]!
    @relationship(type: "INCLUDES_TEST", direction: OUT, properties: "AssertedEdgeProperties", nestedOperations: [CONNECT], aggregate: false)
    @filterable(byValue: true, byAggregate: false)
  """class: asserted; cardinality: many (stored Product → LabTest; D6 Product is the purchasable item that delivers this test); questions: Q-D4-01, Q-D4-10, Q-D4-13, Q-D4-18, Q-D4-24."""
  products: [Product!]!
    @relationship(type: "DELIVERS", direction: IN, properties: "AssertedRecordedProperties", nestedOperations: [CONNECT], aggregate: false)
    @filterable(byValue: true, byAggregate: false)
}

enums.sdl:
"verification.v1 adjudication decision (human review of a held result)."
enum AdjudicationDecision {
  AFFIRM
  REJECT
  DEFER
}

"CAPTURE_FIDELITY judges the record against its declared span (feeds Assertion.status); SUPPORT judges whether located evidence supports the proposition (world question; never changes status)."
enum AdjudicationKind {
  CAPTURE_FIDELITY
  SUPPORT
}

enum AeCollectionMethod {
  SYSTEMATIC
  SPONTANEOUS
  NOT_DESCRIBED
}

enum AeSeriousness {
  ANY
  SERIOUS
  NON_SERIOUS
}

enum AllocationKind {
  RANDOMIZED
  NON_RANDOMIZED
  NOT_APPLICABLE
  NOT_REPORTED
}

"Vetting disposition of a claim (00-DIRECTIVE 3.4)."
enum ClaimDisposition {
  IGNORE
  MONITOR
  RESEARCH
}

enum ComparisonKind {
  BETWEEN_ARM
  WITHIN_ARM_CHANGE
  ARM_DESCRIPTIVE
}

"Pinned DiagnosticResultKind: is a value measured, calculated from other values, or inferred by a model (DNAm surrogates, PPG-derived estimates)."
enum DiagnosticResultKind {
  MEASURED
  CALCULATED
  INFERRED
}

"How much a PROGRAM_DISCONTINUATION stops: one trial, the whole program, or the company (wind-down, dissolution)."
enum DiscontinuationScope {
  TRIAL
  PROGRAM
  COMPANY
}

enum EnrollmentCountType {
  ACTUAL
  ESTIMATED
}

enum EstimateQualifier {
  AS_REPORTED
  APPROXIMATE
  READ_FROM_FIGURE
  CALCULATED_BY_BELLLABS
}

"verification.v1 EvidenceEdge.origin."
enum EvidenceOrigin {
  DECLARED
  VERIFIER_FOUND
}

"Role of an exposure attached to a context: the tested agent, a background co-exposure (e.g. exercise training), or the comparator."
enum ExposureRole {
  TESTED
  BACKGROUND
  COMPARATOR
}

"Intake scope of a dose or limit: an upper limit for supplemental magnesium is not comparable with total intake (Q-D5-06)."
enum IntakeScope {
  SUPPLEMENTAL_ONLY
  TOTAL_INTAKE
  NOT_STATED
}

"An orderable/purchasable test as offered: one analyte, a panel of tests, or a report computed by algorithms."
enum LabTestKind {
  SINGLE
  PANEL
  ALGORITHM_REPORT
}

"Family of a LegalStatusKind: market access (may it be sold, as what), exclusivity (who else may rely on the data or sell), IP right (patent and claim standing)."
enum LegalStatusFamily {
  MARKET_ACCESS
  EXCLUSIVITY
  IP_RIGHT
}

"Licence-level market status, separate from licence status (LNHPD: 'Licence Status: Active' with 'Market status: Not Marketed')."
enum MarketStatus {
  MARKETED
  NOT_MARKETED
  UNKNOWN
}

"Access class. There is no private-personal value; null is not public (fail closed)."
enum PrivacyClass {
  PUBLIC
  INTERNAL
}

enum RegistryDateType {
  ACTUAL
  ANTICIPATED
}

"Granularity of a ReportItem. Sentences are not graph nodes: they stay in the sealed report ledger (verification.v1 report_assertion with offsets) and are reached through the item's body offsets."
enum ReportItemKind {
  SECTION
  ROW
}

"Pinned RequirementBasis (kept): who decided the requirement level."
enum RequirementBasis {
  STATED_BY_SOURCE
  EDITORIAL_INFERENCE
  NOT_STATED
}

enum SexScope {
  ALL
  FEMALE
  MALE
  NOT_REPORTED
}

enum StudyPopulationKind {
  ELIGIBLE
  ENROLLED
  RANDOMIZED
  ANALYZED
}

"Lifecycle of a vocabulary target (vocab-targets.yaml); a deprecated target keeps its node and names `replacedBy`."
enum TargetStatus {
  ACTIVE
  DEPRECATED
}

"How a RegistrationVersion entered the graph: captured by BellLabs (its own snapshot) or reconstructed from a dated history statement inside a later snapshot (ISRCTN 'Amended dd/mm/yyyy', editorial notes)."
enum VersionPopulatingMode {
  OBSERVED
  RECONSTRUCTED
}
